pnpm eslint . --format json 2>/dev/null | node -e "
const data = JSON.parse(require('fs').readFileSync(0, 'utf8'));
const counts = {};
let files = 0, errs = 0, warns = 0;
for (const f of data) {
  if (f.messages.length) files++;
  errs += f.errorCount; warns += f.warningCount;
  for (const m of f.messages) {
    const key = m.ruleId || 'parse-error';
    counts[key] = (counts[key] || 0) + 1;
  }
}
console.log('files with issues:', files, '| errors:', errs, '| warnings:', warns);
const sorted = Object.entries(counts).sort((a,b) => b[1]-a[1]);
for (const [rule, n] of sorted) console.log(String(n).padStart(6), rule);
"

pnpm eslint . --format json 2>/dev/null | node -e "
const data = JSON.parse(require('fs').readFileSync(0, 'utf8'));
const byDir = {};
const syntaxKind = {};
const parseErrFiles = [];
for (const f of data) {
  if (!f.messages.length) continue;
  const rel = f.filePath.replace(process.cwd() + '/', '');
  const isTest = /test|__tests__|snapshots/.test(rel);
  const top = (isTest ? 'TEST:' : '') + rel.split('/').slice(0, 2).join('/');
  byDir[top] = (byDir[top] || 0) + f.messages.length;
  for (const m of f.messages) {
    if (!m.ruleId) parseErrFiles.push(rel);
    if (m.ruleId === 'no-restricted-syntax') {
      const kind = m.message.split('.')[0].split(' is banned')[0];
      syntaxKind[kind] = (syntaxKind[kind] || 0) + 1;
    }
  }
}
console.log('── issues by area (top 20) ──');
Object.entries(byDir).sort((a,b)=>b[1]-a[1]).slice(0,20).forEach(([d,n])=>console.log(String(n).padStart(6), d));
console.log('── no-restricted-syntax breakdown ──');
Object.entries(syntaxKind).sort((a,b)=>b[1]-a[1]).forEach(([k,n])=>console.log(String(n).padStart(6), k));
console.log('── parse-error files ──');
[...new Set(parseErrFiles)].slice(0,15).forEach(f=>console.log('  ', f));
"

