cd /private/tmp/claude-501/-Users-t-vilaverde-Workspace-panlogion-yap/aea7463d-ddb2-43fa-8d0e-e921d31c38d1/scratchpad && node -e "
const fs = require('fs');
const data = JSON.parse(fs.readFileSync('eslint.json', 'utf8'));
// per-rule: up to 6 sample sites with the offending source line, skipping gitignored artifacts
const skip = /\/(bin|dist|coverage)\//;
const samples = {};
for (const f of data) {
  if (skip.test(f.filePath)) continue;
  const rel = f.filePath.replace(/^.*panlogion\/yap\//, '');
  const src = f.source ? f.source.split('\n') : null;
  for (const m of f.messages) {
    const rule = m.ruleId || 'parse-error';
    samples[rule] = samples[rule] || { count: 0, sites: [] };
    samples[rule].count++;
    if (samples[rule].sites.length < 6) {
      const line = src && src[m.line - 1] ? src[m.line - 1].trim().slice(0, 130) : '';
      samples[rule].sites.push(rel + ':' + m.line + '  ' + line);
    }
  }
}
const order = Object.entries(samples).sort((a, b) => b[1].count - a[1].count);
for (const [rule, { count, sites }] of order) {
  console.log('════ ' + rule + '  (' + count + ')');
  sites.forEach(s => console.log('   ' + s));
}
" > rule-samples.txt; wc -l rule-samples.txt

