pnpm eslint . --format json 2>/dev/null | node -e "
const data = JSON.parse(require('fs').readFileSync(0, 'utf8'));
let imports = 0, locals = 0;
for (const f of data) {
  const src = f.source ? f.source.split('\n') : [];
  for (const m of f.messages) {
    if (m.ruleId !== '@typescript-eslint/no-unused-vars') continue;
    const line = (src[m.line - 1] || '').trim();
    /^import\b|^\s*import\b/.test(line) ? imports++ : locals++;
  }
}
console.log('unused imports:', imports, '| unused locals/params:', locals);
"

