		it("multiple sequential polymorphic lets", () => {
			const src = `{
				let id1 = \\x -> x;
				let id2 = \\y -> y;
				let id3 = \\z -> z;
				let a = id1 1;
				let b = id2 true;
				let c = id3 42;
			}`;

			const res = elaborateFrom(src);

			expect(res.structure.term.type).toBe("Block");
