	maxQuantifierRounds: number;
	maxMbqiTermsPerSort: number;
	trace: "silent" | "collect";
};

export type Env = {
	config: Config;
	problem?: Problem;
};

export type Problem = {
	original: IVL.Formula;
	normalized?: IVL.Formula;
	skolemized?: IVL.Formula;
};

