import * as NF from "@yap/elaboration/normalization";

import * as V2 from "@yap/elaboration/shared/monad.v2";

import * as F from "fp-ts/lib/function";
import * as A from "fp-ts/lib/Array";
import * as R from "fp-ts/lib/Record";
import { mapKeys } from "lodash";

export const replay = function* <T>(action: (zonker: Record<number, NF.Value>) => V2.Elaboration<T>): Generator<V2.Elaboration<any>, T[], any> {
	const ctx = yield* V2.ask();
	const state = yield* V2.getSt();

	if (R.isEmpty(state.nondeterminism.solution)) {
		return [yield* V2.pure(action(ctx.zonker))];
	}

	const zonkers = F.pipe(
		state.nondeterminism.solution,
		R.sequence(A.Applicative),
		A.map((values): Record<number, NF.Value> => {
			const z: Record<number, NF.Value> = mapKeys(values, (_, key) => parseInt(key, 10));
			return z;
		}),
	);

	const answers: T[] = [];
	for (const z of zonkers) {
		const answer = yield action(z);
		answers.push(answer);
	}

	return answers;
	// return F.pipe(
	//     A.zipWith(answers, answers.slice(1), (v1, v2) => unify(v1, v2, ctx.env.length, Sub.empty)(ctx)),
	//     A.map(([{ result }]) => result),
	//     E.sequenceArray,
	//     E.map(_ => answers[0])
	// )
};

import * as EB from "@yap/elaboration";
import * as V2 from "@yap/elaboration/shared/monad.v2";
import { Patterns } from "@yap/elaboration";
import * as NF from "@yap/elaboration/normalization";
import * as Src from "@yap/src/index";

import * as Q from "@yap/shared/modalities/multiplicity";

import * as F from "fp-ts/function";

import { match } from "ts-pattern";

import * as P from "@yap/elaboration/shared/provenance";

type Match = Extract<Src.Term, { type: "match" }>;

export const infer = (tm: Match): V2.Elaboration<EB.AST> =>
	V2.track(
		{ tag: "src", type: "term", term: tm, metadata: { action: "infer", description: "Match" } },
		V2.Do(function* () {
			const ctx = yield* V2.ask();
			const ast = yield* EB.infer.gen(tm.scrutinee);
			const alternatives: AltNode[] = yield V2.traverse(tm.alternatives, elaborate(ast, EB.infer));

			// Ensure all alternatives have the same type - we pick the type of the first alternative as the common type
			const common = alternatives[0][1];
			yield V2.traverse(alternatives, ([_alt, ty, _us], i) => {
				const provenance: P.Provenance[] = [
					{
						tag: "alt",
						alt: tm.alternatives[i],
						metadata: {
							action: "alternative",
							type: ty,
							motive: `attempting to unify with previous alternative of type ${NF.display(ty, ctx)}:\t${Src.Alt.display(tm.alternatives[i])}`,
						},
					},
					{ tag: "src", type: "term", term: tm.alternatives[i].term, metadata: { action: "infer", description: "" } },
				];
				return V2.track(
					provenance,
					V2.Do(() => V2.tell("constraint", { type: "assign", left: ty, right: common, lvl: ctx.env.length })),
				);
			});

			// TODO: Also deal with usage semantics
			const [scrutinee, _scuty, sus] = ast;
			const match = EB.Constructors.Match(
				scrutinee,
				alternatives.map(([alt]) => alt),
			);
			const kind = NF.Constructors.Var(yield* EB.freshMeta(ctx.env.length, NF.Type));
			const matchTy = NF.Constructors.Var(yield* EB.freshMeta(ctx.env.length, kind));

			const constraints = alternatives.map(([, ty]): EB.Constraint => ({ type: "assign", left: ty, right: matchTy, lvl: ctx.env.length }));
			yield* V2.tell("constraint", constraints);

			return [match, matchTy, sus] satisfies EB.AST;
		}),
	);
infer.gen = F.flow(infer, V2.pure);

/**
 * 
	TODO: Allow for returning a Variant type    
	TODO: Augment the context with the scrutinee narrowed to the pattern   
 */
export type AltNode = [EB.Alternative, NF.Value, Q.Usages];
export const elaborate =
	([_scrutinee, scuty, _sus]: EB.AST, action: (alt: Src.Term, pat: EB.Patterns.Result) => V2.Elaboration<EB.AST>) =>
	(alt: Src.Alternative): V2.Elaboration<AltNode> =>
		V2.track(
			{ tag: "alt", alt, metadata: { action: "alternative", motive: "elaborating pattern", type: scuty } },
			(() => {
				const extend = (binders: Patterns.Binder[]) => (ctx_: EB.Context) =>
					binders.reduce((ctx, [name, va]) => EB.bind(ctx, { type: "Lambda", variable: name }, va), ctx_);

				const inferAltBy =
					<K extends keyof Patterns.Inference<Src.Pattern, "type">>(key: K) =>
					(alt: Src.Alternative & { pattern: Extract<Src.Pattern, { type: K }> }) =>
						V2.Do(function* () {
							const inferred = yield* Patterns.infer[key].gen(alt.pattern);
							const [pat, patty, _patus, binders] = inferred;
							yield* V2.tell("constraint", { type: "assign", left: patty, right: scuty });

							const node = yield* V2.local(
								extend(binders),
								V2.Do(function* () {
									const [branch, branty, brus]: EB.AST = yield action(alt.term, inferred);
									return [EB.Constructors.Alternative(pat, branch, binders), branty, brus] satisfies AltNode;
								}),
							);
							return node;
						});

				const r = match(alt)
					.with({ pattern: { type: "lit" } }, inferAltBy("Lit"))
					.with({ pattern: { type: "var" } }, inferAltBy("Var"))
					.with({ pattern: { type: "struct" } }, inferAltBy("Struct"))
					.with({ pattern: { type: "tuple" } }, inferAltBy("Tuple"))
					.with({ pattern: { type: "variant" } }, inferAltBy("Variant"))
					.with({ pattern: { type: "list" } }, inferAltBy("List"))
					.with({ pattern: { type: "wildcard" } }, inferAltBy("Wildcard"))

					.otherwise(alt => {
						throw new Error(`Pattern Matching for ${alt.pattern.type}: Not implemented`);
					});

				return r;
			})(),
		);

import * as EB from "@yap/elaboration";
import * as V2 from "@yap/elaboration/shared/monad.v2";

import * as NF from "@yap/elaboration/normalization";
import * as Q from "@yap/shared/modalities/multiplicity";
import * as Src from "@yap/src/index";

import * as F from "fp-ts/function";
import * as R from "@yap/shared/rows";

import { entries, setProp } from "@yap/utils";

type TRow = Extract<Src.Term, { type: "row" }>;

export const infer = (term: TRow): V2.Elaboration<EB.AST> =>
	V2.track(
		{ tag: "src", type: "term", term, metadata: { action: "infer", description: "Row" } },
		V2.Do(() =>
			V2.local(
				EB.muContext,
				V2.Do(function* () {
					const { fields, tail } = yield* withLabelContext.gen(term.row, collect(term.row));

					if (tail) {
						throw new Error("Row literals with tails are not supported");
					}

					const tm = fields.reduce<EB.Row>((r, { label, term }) => R.Constructors.Extension(label, term, r), R.Constructors.Empty());
					return [EB.Constructors.Row(tm), NF.Row, Q.noUsage(0)] satisfies EB.AST;
				}),
			),
		),
	);
infer.gen = F.flow(infer, V2.pure);

// TODO:FIXME update the label env to a stack to properly handle nested row types
export const withLabelContext = <A>(row: Src.Row, f: V2.Elaboration<A>): V2.Elaboration<A> =>
	V2.Do(function* () {
		const ctx = yield* V2.ask();
		const bindings = yield* extract(row, ctx.env.length);
		return yield* V2.local(
			ctx_ =>
				entries(bindings).reduce((ctx, [label, type]) => {
					const withLabel = EB.extendLabel(ctx, label, type);
					const neutral = NF.Constructors.Neutral(NF.Constructors.Var({ type: "Label", name: label }));
					return { ...withLabel, sigma: { ...withLabel.sigma, [label]: { value: neutral } } };
				}, ctx_),
			f,
		);
	});
withLabelContext.gen = <A>(row: Src.Row, f: V2.Elaboration<A>) => V2.pure(withLabelContext(row, f));

type Collected = { fields: { label: string; term: EB.Term; value: NF.Value }[]; tail?: { variable: EB.Variable; ty: NF.Value } };
export const collect = (row: Src.Row): V2.Elaboration<Collected> =>
	V2.Do(function* () {
		const ctx = yield* V2.ask();

		const initial: Collected = { fields: [] };
		const collected: Collected = yield R.fold<Src.Term, Src.Variable, V2.Elaboration<Collected>>(
			row,
			(val, lbl, acc) =>
				V2.Do(function* () {
					const [vtm, vty, _qs] = yield* EB.infer.gen(val);
					const type = ctx.labels[lbl];
					if (!type) {
						throw new Error("Elaborating Row Extension: Label not found");
					}

					//const nf = NF.evaluate(ctx, vtm);
					yield* V2.tell("constraint", [{ type: "assign", left: vty, right: type }]);

					const accumulated: Collected = yield acc;
					return { fields: [...accumulated.fields, { label: lbl, term: vtm, value: vty }], tail: accumulated.tail };
				}),
			(v, acc) =>
				V2.Do(function* () {
					const [tm, ty, _qs] = yield* EB.lookup.gen(v, ctx);
					if (tm.type !== "Var") {
						throw new Error("Elaborating Row Var: Not a variable");
					}

					const unwrapped = NF.unwrapNeutral(ty);

					const accumulated: Collected = yield acc;
					return { fields: accumulated.fields, tail: { variable: tm.variable, ty: unwrapped } };
				}),
			V2.of(initial),
		);

		return collected;
	});
collect.gen = F.flow(collect, V2.pure);

export const extract = function* (row: Src.Row, lvl: number): Generator<V2.Elaboration<any>, Record<string, NF.Value>, any> {
	if (row.type === "empty") {
		return {};
	}

	if (row.type === "variable") {
		return {};
	}

	const type = NF.Constructors.Flex(yield* EB.freshMeta(lvl, NF.Type));

	const rest = yield* extract({ ...row.row, location: row.location }, lvl);
	return setProp(rest, row.label, type);
};

